INSERT INTO transfer_targets VALUES(10,'AVL','2026-summer','Modou Kéba Cissé','시세','시세',57,1944705,'LASK → Aston Villa','CB','RCB','CONFIRMED',NULL,'001100013201476027X812666',60.89999999999999858,31.19999999999999929,29,7.099999999999999645,'cb_defender','Balanced','cb_bpd','Aggressive',0.8830000000000000071,'CONFIRMED incoming: pre-contract signed summer 2025, joins for 2026/27 after a season at LASK. Measured: right-of-centre CB (60.9,31.2), Ball-Playing Defender/Aggressive fit 0.89 — same fit family as Konsa (0.88). Natural RCB cover/heir; Austrian Bundesliga level caveat. [2026-07-15 재확인] RotoWire: 공식 합류 확인(사전계약, LASK에서 2026년 여름 발효). [2026-07-15 3축+스탯 — 유지] 6경기: kp 0·xA .01·듀얼 3.8·태클 1.5·패스 84% — 진전 산출 없는 수비형, cb_defender/Balanced 처방 유지(움직임은 bpd/Aggressive .89로 콘사형 스텝아웃 — 기능축 우선). LASK 리그 수준 캐비앗. [2026-07-28 FC26 통합 확인] 숙련 cb_defender+·cb_stopper+ — bpd 마커 없음, 기능축 처방(cb_defender/Balanced)을 FC26이 지지 — 확정.','SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured','실측 HIGH — 25/26 전수 29경기.  커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(13,'AVL','2026-summer','Alysson','알리송',NULL,59,1631879,'Aston Villa (2026-01, Grêmio €10M)','RW','RM','OWNED',NULL,'001331015X001370003500013',83.20000000000000284,59.70000000000000284,22,6.879999999999999894,'wm_winger','Balanced','wm_widemid','Build-Up',0.8329999999999999627,'ALREADY OWNED: joined from Grêmio for €10M in January 2026; young (2006) right winger not yet in the analysis roster. Measured: genuine wide-right (83.2,59.7) — the squad''s only natural touchline RW; fit Inside Forward/Balanced 0.85. Prescription Winger/Attack to use his width+pace profile distinct from McGinn/Bowen half-space types. [2026-07-15 3축+스탯 — 유지] 6경기: xG .10·xA .03·kp .3·듀얼 3.7·드리블 1.0 — 창조 산출 미성숙 직선 윙어, winger/Attack 처방 유지(움직임 최근접은 insidefwd/Balanced .847). [2026-07-29 우측 브리프 정합 검증] 디아비 템플릿 코사인 .839, 침투 서명 전방 0.54·자기진영 0.23(하지무사·음바예보다 낮음 = 침투 빈도 열위), 터치라인 열 0.60 = 스쿼드 유일 천연 터치라인 RW. 함의: 브리프를 부분 충족하는 보유 자원이라 "우측이 절대 공백은 아니다"는 협상 레버리지. 19세로 주전 고정은 리스크.','SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured','실측 HIGH — 25/26 전수 22경기.  커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(30,'AVL','2026-summer','Tammy Abraham','타미 아브라함',NULL,60,610766,'Aston Villa','ST','ST','OWNED',NULL,'239324777256X732212211410',47.39999999999999858,59.0,25,6.950000000000000177,'st_target','Attack','st_false9','Attack',0.6430000000000000159,'ALREADY OWNED: 2026-01-27 베식타슈에서 ~£18m로 빌라 복귀(1일 만에 재이적), 그 시즌 유로파리그 우승. 여름 루머 대상이 아니라 보유 선수(알리송과 동일 케이스) — 사용자 요청으로 OWNED ST 옵션으로 편입. 실측(반시즌 통틀어 45분+ 4경기 전부 ST): 중앙-약간좌측·깊은 풋프린트 (47.4,59.0), 평균 6.85. 최근접 st_false9/Attack 0.52 — 왓킨스(st_advanced 자기커널)·기라시 0.80·브로베이 0.75·파르도 0.87보다 명확히 낮음. 처방은 타깃/홀드업 아키타입 반영 st_target/Attack. 표본 캐비앳: 왓킨스의 로테이션 백업이라 45분+ 경기가 반시즌 4경기뿐이고 전부 교체 출전(추격 상황 드롭) → 깊은 편향된 풋프린트, 선발 표본 아님. [2026-07-15 3축+스탯 — 유지] 6경기: xG .25·3골·kp 1.0·드리블 0 — 타깃형 피니셔, st_target/Attack(공중 플랜B, obs#19) 유지.','SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured','실측 HIGH — 25/26 전수 25경기.  커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(77,'AVL','2026-summer','Johan Manzambi','만잠비','만잠비',55,1518931,'SC Freiburg','CM','LDM','CONFIRMED',NULL,'33423X9565897636965322311',43.60000000000000142,51.79999999999999716,56,7.200000000000000177,'dm_dlp','Roaming','dm_dlp','Roaming',0.7129999999999999672,'완전 box-to-box, 중앙 전역 커버(온아나 대체). 실측 6경기(분데스리가, 363pt) 중심 tool(44,52). 커널 fit LDM dm_dlp/Roaming 0.812 (RDM는 0.544로 약함 → 좌중앙 성향, LDM 전용). 평균 7.62 최상. [2026-07-14 확정] 빌라 합류 확정(사용자 확인). [2026-07-15 재확인] Romano "here we go": €60m+ 구두합의, 개인조건 완료. 뉴캐슬 £49m 구두합의를 히잭. 아직 공식 발표(메디컬) 전 단계. [2026-07-15 3축+스탯 — 유지] 6경기: 듀얼 7.5(후보군 1위)·xG .18·xA .16·태클 1.8·평점 7.40 — 박투박+창조 겸비(오나나 공백 임무에도 부합), dlp/Roaming 유지. [2026-07-17 재확인] 메디컬 완료(7/16), Romano "몇 시간 내 발표". Visit Rwanda 스폰서 관련 잡음(DRC 가족사) 해소, 5년 계약 — 클럽 레코드 £50m+. [2026-07-18 재확인] 공식 발표 완료(7/17 저녁) — £59.5m(€70m) 클럽 레코드, 장기계약. 뉴캐슬 하이잭 최종 성사. [2026-07-21 멀티포지션] CAM(대표팀 전진 실측 0.817)·LM(재배치 0.700) 행 추가 — 슬롯별 별도 그리드 참조. [2026-07-28 FC26 통합 확인] LDM: 숙련 dm_dlp+·cm_dlp+가 처방과 일치 — 확정. 테크니컬 PS·드리블85.','SofaScore API 25/26 전수 재수집 (2026-08-11) — player_role_map kind=measured','실측 HIGH — 25/26 전수 56경기. 클럽(프라이부르크) 44경기 통합 — 딥 역할 표본 커널 적합은 docs/20 회귀 게이트 통과 구현으로 산출. ⚠️ 2026-08-11 이전 값은 4~6경기 표본이었다.');
INSERT INTO transfer_targets VALUES(91,'AVL','2026-summer','João Palhinha',NULL,'팔리냐',75,364612,'Bayern Munich','DM','LDM','DEAD (바이에른 공개 결렬 — 임대 vs €30m 완전이적 구조 이견, 2026-08-14 에베를/Romano)','2026-08-15','012113536536797368X712431',57.0799999999999983,44.96000000000000085,34,7.160000000000000142,'dm_dlp','Roaming','dm_dlp','Roaming',0.7089999999999999636,'바이에른과 시즌 로그론 + €25m 의무구매옵션 가능성 합의, 잉글랜드 이동 중(오나나 부상 공백 메우기). 온나나 십자인대 부상, 틸레만스 맨유行으로 보강 필요. [2026-07-27 21시 최신화] 로마노/애슬레틱(Tanswell) 경유: 팔리냐가 잉글랜드로 이동해 임대(+콜옵션 €25m) 마무리 단계 — 벤피카를 제치고 빌라가 사실상 확보. 다만 Tanswell은 "완전히 무산된 건 아니지만 빌라가 다른 일들로 바빠 잠시 정체"라고 톤 조절. 바이에른은 매각 강력 희망(€100m 펀드 확보 목적). [2026-07-28 FC26 통합 확인] 숙련 dm_holding+(수비/볼위닝/로밍)가 기능축 처방과 정확 일치 — 확정. DEF83/PHY84/공격성91/태클85·슬라이딩태클/브루저 PS. 캐비앗: 네거티브 PS "부상에 취약함". [2026-07-29 14시 재확인 — HIGH 유지] Plettenberg(Sky DE): 7/19 "영국행·합의" 보도 반박 — 합의 없음, 프리시즌 바이에른 합류. 현 상태: 빌라=대여+옵션 고수 vs 바이에른=€25m 완전이적 요구 교착. BILD "빌라가 바이에른의 최유력 매각처". 사우디·터키 관심 있으나 선수는 유럽 잔류 희망(가족). [경쟁구도 2026-07-30] 빌라 우위 — 경쟁 대안(벤피카·스포르팅)은 마르쿠 실바 재결합 등 동기는 있으나 €25m 지불 능력이 없고, 사우디·터키 공식 오퍼는 선수가 거부. 바이에른 SD Freund가 7/28 공개 발언("다음 단계는 다른 곳에서")으로 매각 기조 확정, BILD는 빌라를 최유력 매수처로 서술. 교착 지점은 클럽 경쟁이 아니라 구조(임대+옵션 vs 완전 €25m)와 선수 본인 결정. 선수 선호는 자녀 거주지(포르투갈) 근접이지만 자금이 그 선호를 봉쇄. [경쟁구도 2026-08-01 — 빌라 우위 → **대등**으로 하향] 뉴캐슬 참전: ESPN Brasil(Bruno Andrade 기명)이 뉴캐슬이 브루누 기마랑이스 아스날행 대비 미드필더 2인과 협상 중이며 그중 하나가 팔리냐라고 보도. 뉴캐슬은 기마랑이스 매각 ~€93m(+토날리 €117m 기수령)으로 **지불력이 빌라 £40m 상한(Tanswell)보다 명확히 우위**. 바이에른 측: Falk — 바이에른이 더는 합의를 자신하지 못하며, 선수 본인이 "요구액 미인하 시 잔류도 감수"로 **레버리지를 쥠**. Eberl이 매각 대상 3인에 공개 포함, 완전이적 **€30m 근접액 요구**(07-30 €25m에서 상향). 구조 교착(빌라 임대+옵션 vs 바이에른 완전이적)은 불변. §2-1 보정표상 "경쟁 클럽 우위"가 아니라 "대등"이므로 **등급은 HIGH 유지**. [2026-08-02 경쟁구도 재판정 — 대등 → **빌라 우위**로 되돌린다] ⚠️ **어제(08-01) 하향은 과잉 해석이었다.** 근거로 쓴 ESPN Brasil(Bruno Andrade) 기사는 뉴캐슬이 기마랑이스 대체 **숏리스트 2인**을 추렸고 그중 하나가 팔리냐라는 내용까지이며, **협상 단계라고 쓰지 않았다** — 나는 "지불력 우위(€93m)"를 "단계 우위"로 읽었다. 오늘 독립 확인 결과 **뉴캐슬의 입찰 보도는 없고 관심·숏리스트 단계**이며, 빌라는 **수 주간 바이에른과 협상 중**(돌파구 없음)이다. 단계 비교(협상 > 관심)에서 빌라가 앞선다. ⚠️ 단 오늘 검색은 **빌라의 공식 입찰(formal bid) 제출도 확인하지 못했다** — 스캔 에이전트의 "빌라만 공식 입찰" 서술은 채택하지 않는다. 교착 요인 불변: 빌라 임대+옵션 vs 바이에른 완전이적 €30m 근접, Falk "바이에른이 더는 합의를 자신하지 못한다", 선수는 잔류도 감수 + 사우디 오퍼 거절. [경쟁구도 2026-08-03 22시 — 뉴캐슬 항 하향] ⭐ **에디 하우가 2026-07-31 뉴캐슬 감독직에서 사퇴했다**(구단 공식 발표 + Sky Sports + ESPN = 1티어 3중). 브리스톨 시티전 1-4 패배 직후이고, 사유는 개인 재충전이나 배경으로 **어려운 여름 이적창**(토날리·고든 매각)이 병기된다. 후임 미임명(Jaissle 유력, "advanced stage"), 개막(8/23 리버풀)까지 25일. → **감독 부재 상태의 중원 숏리스트는 집행력이 없다**. 다만 반대 방향 요인이 병존한다: 기마랑이스→아스날 €93m이 성사되면 **자금은 오히려 늘어난다**. 정확한 서술은 **"자금은 늘고 집행 주체는 사라진 상태"**다. ⚠️ 이 사실은 08-03 09시·21시 두 섹션이 모두 놓쳤다 — 경쟁 클럽 링크를 **숏리스트 등재 여부로만** 추적하면 상대 구단의 **제도적 집행력 변화**를 놓친다는 사례로 남긴다. 빌라 등급 HIGH·단계는 불변(병목은 여전히 바이에른의 완전이적 €25~30m 고수). [2026-08-06 22시 갱신 — HIGH 유지, 발행일 확정] 09시에 "Bild 보도·발행일 미확정"으로 남겨둔 건이 확정됐다: Sport1(2026-08-06)·Sport BILD가 바이에른의 **€25m 요구를 빌라가 거부**해 재정 조건에서 교착이라고 보도. 신규 사실 — 양 구단이 **08-07 홍콩 카이탁 친선전(Audi Football Summit)을 계기로 대면 협상**을 갖는다. [반대 신호] 팔리냐 본인이 Abendzeitung에 "바이에른에서 자리를 지키는 것이 계획"이라 발언(단, 측근은 오퍼 청취 지속·바이에른 26/27 1군 명단 제외·스포르팅 디렉터 Freund도 장기 계획 밖임을 인정). 단계는 "협상(교착)" 유지 — 오퍼 제출·개인합의 보도 0건이라 상향 불가. [2026-08-07 09시 재확인 — HIGH 유지, 협상 미개최] 어제 예고된 홍콩 대면 협상은 **아직 열리지 않았다** — 친선전 킥오프가 08-07 14:00 CEST(21:00 KST)이고 독일 매체는 협상을 "경기 전후"로 예고했다. 즉 결과는 오늘 21시 회차의 대상이다(Sport1도 "결과는 아직 없다"고 명시). **08-06 이후 신규 사실 2건**: ⑴ **Eberl(바이에른 단장)이 팔리냐·Boey·Zaragoza에 대해 "바이에른에 미래는 없다"고 공개 발언** — 08-06의 Freund 인정보다 강한 공식 톤. ⑵ **임대+옵션·임대+의무매입 등 대안 구조도 이미 시도됐으나 합의 실패** — 교착이 총액뿐 아니라 구조 협상까지 소진된 상태다. 선수 입장은 변화 없음(잔류가 계획, 측근은 오퍼 청취 지속). 콤파니 중원 서열은 키미히·파블로비치·비쇼프·바라 은디아예. ⚠️ 발행일 함정 회피 1건: givemesport "Villa handed huge boost"(Falk/BILD 경유, 바이에른 호가 인하·임대 수용 가능성)는 **2026-07-21자**라 신선한 진전이 아니다. [2026-08-08 09시 재확인] 홍콩 친선전(08-07, 바이에른 2-1 승) 종료 후 빌라 SD Damian Vidagany가 Sport Bild에 직접 발언: "We are in talks, but there is currently no agreement." 바이에른 요구 €20-25m, 여전히 가격차 교착 — 단계 진전 없음. HIGH 유지. [2026-08-09 09시 재확인 — HIGH 유지] 빌라가 임대+의무매입옵션(단계적 지불) 구조를 대안으로 모색 중이나 바이에른은 완전이적(€25m) 우선 — 구조 교착 그대로. 선수 본인은 "요구액 인하 없으면 잔류도 감수"라는 입장 유지, 뮌헨 잔류 시 연봉 €10m+보너스 €2m 부담이 빌라 PSR에 걸림돌이라는 재정 분석 추가(신규 사실 아님, 정황 보강). 홍콩 대면협상 이후 추가 협상 진전 보도 없음. [2026-08-10 09시 재확인 — HIGH 유지] 단계·구조 전부 불변(빌라=1년 임대 스톱갭 선호 vs 바이에른=완전이적 €25m 고수). Vidagany 공식 발언 "협상 중이나 현재 합의 없음"이 최신 상태 그대로. [경쟁구도 신규] 뉴캐슬이 팔리냐 경쟁에 참전한다는 보도가 등장 — 단계는 관심 수준이고 빌라는 구단 공식 확인 협상 단계라 §2-1상 빌라 우위 유지, 등급 보정 없음. ⚠️[2026-08-10 자기정정] 이 회차의 갱신 내용은 **발행일 확정 실패**다 — Moretto 건은 TransferFeed "1h ago" 스탬프(수집 시각이지 발행 시각이 아님, §1)에만 근거하고 원문 날짜를 잡지 못했다. §2-0에 따라 last_news_date를 08-09로 되돌린다(STALE 시계는 확정된 보도일로만 움직인다). [2026-08-10 21시 — 경쟁 강도 하향 정정] 어제 기록한 "뉴캐슬 참전"의 실체가 드러났다: **뉴캐슬의 1순위는 마르세유의 Højbjerg이고 팔리냐는 그 대안으로 거론된 것**이다. 즉 뉴캐슬은 팔리냐를 주 타깃으로 쫓고 있지 않다 → §2-1 경쟁 강도를 한 단계 낮춰 읽어야 하며 **빌라 우위가 더 명확**해졌다. 단계는 여전히 불변(Vidagany "협상 중, 합의 없음", 가격 €25m·구조 임대vs완전 교착). ⚠️ 신규 서술: 협상이 **08-12 PSG 슈퍼컵 전에 마무리되지 않을 수 있다**는 전망. [2026-08-10 20시 — ⚠️ 이 rationale 첫 문장("€25m 의무구매옵션 가능성 합의, 잉글랜드 이동 중")은 07월 서사이며 현재 상태가 아니다. 후속 대괄호 항목들이 정본이다.] 사용자 제보("임대 이적 마무리 기사")를 §2-0으로 추적한 결과 원출처는 **A Bola 2026-07-17 19:15 「Palhinha a um passo do Aston Villa」**(기사 ID 2026071718151506424가 발행시각 인코딩)이며, 본문은 "토요일 잉글랜드로 이동해 합의를 마무리할 예정"이다. **그 이동도 합의도 일어나지 않았다** — 이미 Plettenberg(Sky DE)가 07-29에 같은 계열 보도(7/19 영국행·합의)를 반박했고 팔리냐는 바이에른 프리시즌에 합류했다. 즉 이 서사는 **24일 된 무산 건**이고, 재검색 시 상위 노출되므로 재순환 위험이 높다. 병기 확인: 같은 A Bola 계열의 벤피카 대안 구조(임대료 €10m + 의무매입 €15m)는 **bolanarede 2026-07-15**자이고 "제출"이 아니라 "제출 예정"이었다 — 이후 벤피카는 지불력 부족으로 탈락했다(07-30 판정). **현 상태 불변**: Vidagany 공식 "협상 중, 합의 없음"(08-07~08), 바이에른 €25m 완전이적 고수, 구조 교착. 오퍼 제출·개인합의·메디컬 보도 전부 0건. **HIGH 유지, last_news_date 갱신 없음**(신규 발행 확정 원문 없음). | [2026-08-12] HIGH 유지. 교착 지점이 **거래 구조**로 특정됐다 — 빌라는 **매입 옵션부 임대**(토트넘 방식) 선호, 바이에른은 **영구 이적** 선호. The Athletic(1티어) 기준 바이에른 호가 **€30m** 유지. [경쟁구도] 뉴캐슬·벤피카 경쟁 중 TEAMtalk 기준 **빌라 선두**. 오퍼·개인합의·메디컬 전부 0건. 공식 사유는 오나나 ACL 시즌 아웃(Vidagany 발언 근거). [2026-08-13] ⭐ **개인 조건은 이미 완전 합의**(Plettenberg/Sky Germany, 2티어) — 어제 "개인합의 0건"으로 적은 것을 정정한다. 막힌 지점은 **거래 구조 하나**로 좁혀졌다: 빌라의 임대+매입옵션 제안을 **바이에른이 거부**하고 영구 이적을 고수한다. 금액 소스 갈림 — 